CASE_NO_PREFIX = {
    "Criminal": "CRL",
    "Civil/Property": "CIV",
    "Family": "FAM",
    "Labour & Service": "LAB",
    "Consumer": "CON",
    "Tax": "TAX",
    "Constitutional/Writ": "WRT",
    "Contract/Commercial": "COM",
}


# ---------------------------------------------------------------------------
# HELPER FUNCTIONS
# ---------------------------------------------------------------------------

def _rand_name(rng):
    first = rng.choice(MALE_NAMES + FEMALE_NAMES)
    last = rng.choice(SURNAMES)
    return f"{first} {last}"


def _rand_amount(rng):
    base = rng.choice([50000, 75000, 100000, 150000, 200000, 250000, 300000,
                       500000, 750000, 1000000, 1500000, 2000000, 5000000])
    variation = rng.randint(-5, 5) * 1000
    return str(max(10000, base + variation))


def _rand_section(rng):
    return str(rng.choice([34, 80, 125, 138, 143, 147, 192, 226, 271, 304, 438, 482]))


def _rand_stat_name(rng):
    statutes = [
        "Indian Penal Code", "Code of Criminal Procedure", "Income Tax Act",
        "Hindu Marriage Act", "Transfer of Property Act", "Indian Contract Act",
        "Consumer Protection Act", "Industrial Disputes Act",
        "Negotiable Instruments Act", "Arbitration and Conciliation Act",
        "Insolvency and Bankruptcy Code", "Central Goods and Services Tax Act",
    ]
    return rng.choice(statutes)


def _make_citation(court, year, case_type, n):
    abbrev = COURT_ABBREV.get(court, "UNK")
    type_abbrev = TYPE_ABBREV.get(case_type, "GEN")
    return f"{abbrev} {year}/{type_abbrev}{n:04d}"


def _rand_date_in_range(rng, start_date, end_date):
    delta = (end_date - start_date).days
    offset = rng.randint(0, delta)
    return start_date + datetime.timedelta(days=offset)


# ---------------------------------------------------------------------------
# GENERATE JUDGMENTS (400 total = 8 types × 50 each)
# ---------------------------------------------------------------------------

def generate_judgments(seed=42) -> list[dict]:
    """
    Generate 400 synthetic judgments across 8 case types (50 each).
    Pure Python, deterministic seed, slot-filled templates with legal vocabulary.
    Returns list of 400 dicts.
    """
    random.seed(seed)
    rng = random.Random(seed)
    judgments = []
    global_n = 1

    for case_type in CASE_TYPES:
        subtheme_list = SUBTHEMES[case_type]
        court_list = COURTS[case_type]
        outcome_list = OUTCOMES_BY_TYPE[case_type]

        # Gather templates for this case type
        # Special check: for Family, use maintenance_125_family
        type_templates = []
        for st in subtheme_list:
            lookup_key = st
            if case_type == "Family" and st == "maintenance_125":
                lookup_key = "maintenance_125_family"
            tmpls = TEMPLATES.get(lookup_key, TEMPLATES.get(st, []))
            for tmpl in tmpls:
                type_templates.append((st, tmpl))

        # Generate exactly 50 judgments for this case type
        for i in range(50):
            st, template = type_templates[i % len(type_templates)]
            court = rng.choice(court_list)
            year = rng.randint(2015, 2024)
            city = rng.choice(CITIES)
            petitioner = _rand_name(rng)
            respondent = _rand_name(rng)
            amount = _rand_amount(rng)
            section = _rand_section(rng)
            stat_name = _rand_stat_name(rng)
            outcome = rng.choice(outcome_list)

            text = template.format(
                petitioner=petitioner,
                respondent=respondent,
                court=court,
                year=year,
                city=city,
                amount=amount,
                section=section,
                stat_name=stat_name,
            )

            citation = _make_citation(court, year, case_type, global_n)
            title = f"{petitioner} v. {respondent}"

            judgments.append({
                "id": citation,
                "citation": citation,
                "title": title,
                "court": court,
                "year": year,
                "case_type": case_type,
                "subtheme": st,
                "text_content": text,
                "outcome": outcome,
                "petitioner": petitioner,
                "respondent": respondent,
                "city": city,
            })
            global_n += 1

    return judgments


# ---------------------------------------------------------------------------
# GENERATE PENDING CASES (150 total, ~19 per case type)
# ---------------------------------------------------------------------------

def generate_pending_cases(seed=42) -> list[dict]:
    """
    Generate 150 synthetic pending cases distributed across 8 case types.
    Deterministic seed, slot-filled legal descriptions, status weights 40/40/20.
    Returns list of 150 dicts.
    """
    random.seed(seed)
    rng = random.Random(seed + 100)

    today = datetime.date(2026, 11, 24)
    start_filing = datetime.date(2019, 1, 1)
    end_filing = datetime.date(2025, 6, 1)

    status_choices = ["Pending", "Under Hearing", "Judgment Reserved"]
    status_weights = [0.40, 0.40, 0.20]

    # Target: 150 total = 6 types × 19 + 2 types × 18 = 114 + 36 = 150
    counts = {ct: 19 for ct in CASE_TYPES[:6]}
    for ct in CASE_TYPES[6:]:
        counts[ct] = 18

    # Build queue of (case_type, subtheme, desc)
    ordered_items = []
    for ct in CASE_TYPES:
        target_count = counts[ct]
        subthemes_for_type = SUBTHEMES[ct]
        pool = []
        for st in subthemes_for_type:
            descs = PENDING_DESCRIPTIONS.get(st, [])
            for d in descs:
                pool.append((st, d))
        # extend if needed
        extended = pool * ((target_count // len(pool)) + 1)
        rng.shuffle(extended)
        for st, d in extended[:target_count]:
            ordered_items.append((ct, st, d))

    rng.shuffle(ordered_items)

    cases = []
    serials = {ct: 1 for ct in CASE_TYPES}

    for case_id, (case_type, subtheme, description) in enumerate(ordered_items, start=1):
        court = rng.choice(COURTS[case_type])
        filing_date = _rand_date_in_range(rng, start_filing, end_filing)
        hearings_so_far = rng.randint(0, 25)
        num_parties = rng.randint(2, 6)
        is_appeal = rng.randint(0, 1)
        next_days = rng.randint(3, 120)
        next_hearing_date = today + datetime.timedelta(days=next_days)

        # Weighted status selection
        r = rng.random()
        if r < 0.40:
            status = "Pending"
        elif r < 0.80:
            status = "Under Hearing"
        else:
            status = "Judgment Reserved"

        prefix = CASE_NO_PREFIX[case_type]
        court_abbrev = COURT_ABBREV.get(court, "UNK")
        year_filed = filing_date.year
        sn = serials[case_type]
        serials[case_type] += 1
        case_no = f"{prefix}/{court_abbrev}/{year_filed}/{sn:05d}"

        petitioner = _rand_name(rng)
        respondent = _rand_name(rng)
        title = f"{petitioner} v. {respondent}"

        cases.append({
            "id": case_id,
            "case_no": case_no,
            "title": title,
            "description": description,
            "case_type": case_type,
            "court": court,
            "filing_date": filing_date.isoformat(),
            "hearings_so_far": hearings_so_far,
            "num_parties": num_parties,
            "is_appeal": is_appeal,
            "status": status,
            "next_hearing_date": next_hearing_date.isoformat(),
        })

    return cases


